import unittest
import office_calendar as app

class Behavior(unittest.TestCase):
    def test_complete_week(self):
        from datetime import date, timedelta
        monday = date(2026, 5, 4)
        for offset, expected in enumerate([True, True, True, True, True, False, False]):
            with self.subTest(offset=offset):
                self.assertIs(app.is_open(monday + timedelta(days=offset)), expected)
    def test_another_weekend(self):
        from datetime import date
        self.assertIs(app.is_open(date(2024, 2, 24)), False)
        self.assertIs(app.is_open(date(2024, 2, 25)), False)
        self.assertIs(app.is_open(date(2024, 2, 29)), True)

if __name__ == '__main__':
    unittest.main()
